CREATE OR REPLACE FUNCTION public.replace_company_asset(p_company_id uuid, p_asset_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_role not in ('logo','cover') then raise exception 'unsupported company asset role'; end if;
  if not public.has_admin_permission('companies.write') then raise exception 'admin permission denied'; end if;
  delete from public.company_assets where company_id = p_company_id and role = p_role;
  insert into public.company_assets(company_id, asset_id, role, sort_order)
  values (p_company_id, p_asset_id, p_role, 1);
  if p_role = 'logo' then
    update public.companies set logo_asset_id = p_asset_id where id = p_company_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_company_popup_proposal(p_proposal_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS company_popup_proposals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_proposal public.company_popup_proposals%rowtype; v_popup_id uuid;
begin
  if not public.has_admin_permission('popups.write') then raise exception 'ADMIN_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_proposal from public.company_popup_proposals where id=p_proposal_id for update;
  if v_proposal.id is null then raise exception 'POPUP_PROPOSAL_NOT_FOUND' using errcode='P0002'; end if;
  if v_proposal.status<>'pending' then raise exception 'POPUP_PROPOSAL_ALREADY_REVIEWED' using errcode='P0001'; end if;
  if p_approve then
    insert into public.popups(title,body,image_asset_id,action_label,action_url,audience_raw,enabled,start_at,end_at,sort_order,record_origin)
    values(v_proposal.title,v_proposal.body,v_proposal.image_asset_id,v_proposal.action_label,
      case when v_proposal.action_type='url' then v_proposal.action_target else null end,
      v_proposal.audience_raw,false,v_proposal.start_at,v_proposal.end_at,
      coalesce((select max(sort_order)+1 from public.popups),1),'ADMIN_H009') returning id into v_popup_id;
    update public.company_popup_proposals set status='approved',popup_id=v_popup_id,reviewed_by=auth.uid(),reviewed_at=now(),rejection_reason=null where id=p_proposal_id returning * into v_proposal;
  else
    if nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception 'REJECTION_REASON_REQUIRED' using errcode='22023'; end if;
    update public.company_popup_proposals set status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),rejection_reason=btrim(p_reason) where id=p_proposal_id returning * into v_proposal;
  end if;
  return v_proposal;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_section_row_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old jsonb:=case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end;
  v_new jsonb:=case when tg_op='DELETE' then '{}'::jsonb else to_jsonb(new) end;
  v_section text:=tg_argv[0];v_technical text:=tg_argv[1];v_actions text[];v_action text;
  v_origin_col text:=tg_argv[5];v_admin_origin text:=tg_argv[6];v_company uuid;
begin
  if tg_table_name='educational_resources' then
    v_section:=case when coalesce(v_new->>'resource_kind',v_old->>'resource_kind')='tutorial' then 'tutorials' else 'education' end;
    if tg_op='UPDATE' and v_old->>'resource_kind' is distinct from v_new->>'resource_kind' then
      if not public.has_section_action(case when v_old->>'resource_kind'='tutorial' then 'tutorials' else 'education' end,'update')
         or not public.has_section_action(case when v_new->>'resource_kind'='tutorial' then 'tutorials' else 'education' end,'create') then
        raise exception 'SECTION_BOUNDARY_CHANGE_DENIED';
      end if;
    end if;
  end if;
  if auth.role()='service_role' or public.has_admin_permission(v_technical) then return coalesce(new,old);end if;
  -- Preserve the existing company-tenant Marketplace writer without granting it section ownership.
  if tg_table_name in('marketplace_products','marketplace_promotions') then
    v_company:=coalesce((v_new->>'company_id')::uuid,(v_old->>'company_id')::uuid);
    if public.is_marketplace_company_member(v_company,'write') then return coalesce(new,old);end if;
  elsif tg_table_name='marketplace_product_assets' then
    select p.company_id into v_company from public.marketplace_products p where p.id=coalesce((v_new->>'product_id')::uuid,(v_old->>'product_id')::uuid);
    if public.is_marketplace_company_member(v_company,'write') then return coalesce(new,old);end if;
  end if;
  v_actions:=public.section_row_required_actions(v_old,v_new,tg_op,tg_argv[2],tg_argv[3],string_to_array(tg_argv[4],','));
  foreach v_action in array v_actions loop
    if not public.has_section_action(v_section,v_action) then raise exception 'SECTION_ACTION_DENIED:%:%',v_section,v_action;end if;
  end loop;
  if tg_op='INSERT' and v_origin_col<>'' and coalesce(v_new->>v_origin_col,'')<>v_admin_origin then
    raise exception 'ADMIN_ORIGIN_REQUIRED';
  end if;
  if tg_op='DELETE' and v_origin_col<>'' and coalesce(v_old->>v_origin_col,'')<>v_admin_origin then
    raise exception 'HISTORICAL_DELETE_DENIED';
  end if;
  if tg_op='UPDATE' and v_origin_col<>'' and (v_old->v_origin_col) is distinct from (v_new->v_origin_col) then
    raise exception 'RECORD_ORIGIN_IMMUTABLE';
  end if;
  return coalesce(new,old);
end $function$
